BEGIN;
CREATE TABLE IF NOT EXISTS "ServiceCategory" ("id" TEXT NOT NULL PRIMARY KEY, "slug" TEXT NOT NULL UNIQUE, "label" TEXT NOT NULL, "description" TEXT NOT NULL DEFAULT '', "imageUrl" TEXT NOT NULL DEFAULT '', "active" BOOLEAN NOT NULL DEFAULT TRUE, "sortOrder" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "SiteAnnouncement" ("id" TEXT NOT NULL PRIMARY KEY, "title" TEXT NOT NULL, "body" TEXT NOT NULL, "ctaLabel" TEXT, "ctaHref" TEXT, "startsAt" TIMESTAMP(3), "endsAt" TIMESTAMP(3), "active" BOOLEAN NOT NULL DEFAULT FALSE, "sortOrder" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "SiteMediaAsset" ("id" TEXT NOT NULL PRIMARY KEY, "label" TEXT NOT NULL, "description" TEXT NOT NULL DEFAULT '', "mediaType" TEXT NOT NULL, "sourceUrl" TEXT NOT NULL, "storageKey" TEXT, "altText" TEXT NOT NULL DEFAULT '', "published" BOOLEAN NOT NULL DEFAULT FALSE, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "SiteContentPage" ("id" TEXT NOT NULL PRIMARY KEY, "slug" TEXT NOT NULL UNIQUE, "title" TEXT NOT NULL, "body" TEXT NOT NULL, "published" BOOLEAN NOT NULL DEFAULT FALSE, "protected" BOOLEAN NOT NULL DEFAULT FALSE, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "SiteNavigationItem" ("id" TEXT NOT NULL PRIMARY KEY, "label" TEXT NOT NULL, "href" TEXT NOT NULL, "visible" BOOLEAN NOT NULL DEFAULT TRUE, "sortOrder" INTEGER NOT NULL DEFAULT 0, "required" BOOLEAN NOT NULL DEFAULT FALSE, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE "MarketplaceListing" ADD COLUMN IF NOT EXISTS "featured" BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE "MarketplaceListing" ADD COLUMN IF NOT EXISTS "sortOrder" INTEGER NOT NULL DEFAULT 0;
COMMIT;